style.css:
div[style*="width:100%"][style*="height:100%"],
div[style*="height: 100vh"][style*="width: 100vw"],
div[style*="position: fixed"][style*="top: 0"][style*="left: 0"],
div[style*="position: fixed"][style*="width:100%"][style*="height:100%"],
div[style*="position: fixed"][style*="width:100vw"][style*="height:100vh"],
div[style*="z-index: 1000"] {
    display: none !important;
    visibility: hidden !important;
    z-index: -9999999 !important;
}
